// Conceptual representation of GC Root reachability
public class MemoryLeakExample {
    // This static reference is a GC Root; it keeps the List alive for the app's lifetime
    private static List<Object> cache = new ArrayList<>(); 

    public void process() {
        Object localObj = new Object(); // Stack-based reference (GC Root while in scope)
        cache.add(localObj);
    } // localObj reference is popped, but cache holds a reference, preventing collection
}
